// Keyword-based priority + ticket reference. Pure JS, no external calls.
const URGENT = ['outage', 'down', 'urgent', 'refund', 'breach', 'asap'];
return $input.all().map(({ json }) => {
  const text = (json.subject + ' ' + json.message).toLowerCase();
  const priority = URGENT.some((k) => text.includes(k)) ? 'high' : 'normal';
  const ticketRef = 'TKT-' + Date.now().toString(36).toUpperCase();
  return { json: { ...json, priority, ticketRef } };
});
